# Actually let me implement directly
def predict_v3(input_rows, output_rows):
    for i, (inp, out) in enumerate(zip(input_rows, output_rows)):
        left = inp[:4]
        right = inp[5:]

        # Check if there's any overlap in this row
        has_overlap = any(l != 0 and r != 0 for l, r in zip(left, right))

        if has_overlap:
            # When overlap exists, just output left side, subsetting to 4 cols
