# Hmm, let me check if right has "continuous" from start
def is_continuous_from_start(right):
    i = 0
    while i < len(right) and right[i] != 0:
        i += 1
    return i == len(right)

for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    print(f"\n{demo_name}:")
    for i, (inp, out) in enumerate(zip(input_rows, output_rows)):
        left, right = inp[:4], inp[5:]
        cont = is_continuous_from_start(right)
        has_overlap = any(l != 0 and r != 0 for l, r in zip(left, right))
        print(f"  Row {i}: left={left}, right={right}, continuous={cont}, has_overlap={has_overlap}, has_2_in_output={2 in list(out)}")

# Count positions of 2s on right side
def right_2_positions(right):
    return [j for j, x in enumerate(right) if x == 2]

def has_all_three_right_twos(right):
    """Does right have 2s in positions 0, 1, 2? (first 3 positions)"""
    return all(right[j] == 2 for j in range(3))

print("D1 rows 0-1 have all_three=True?")
for i in [0, 1]:
