# Let's look at the lowest position where 2 appears on the right
# D1 has 2s further "away" from column 5 (more rightward = higher column index)
# D2 has 2s closer to column 5

def leftmost_2_pos(right):
    """Return the column index of the leftmost 2"""
    for j, x in enumerate(right):
        if x == 2:
            return 5 + j  # Column index
    return None

for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
