# Let me try a DIFFERENT rule: 
# The output width is NOT always 4 - it's the COUNT of all non-zero cells

def count_nonzero(row):
    left = row[:4]
    right_beyond = row[5:9]
    return sum(1 for x in left if x != 0) + sum(1 for x in right_beyond if x != 0)

print("Nonzero counts:")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    for i, (inp, out) in enumerate(zip(input_rows, output_rows)):
        nc = count_nonzero(inp)
        print(f"  {demo_name} Row {i}: count={nc}, len(out)={len(list(out))}")

# Let me try the simplest possible rule:
# Output = merge of left and right, where:
# - If right[j] == 2 OR left[j] == 1, then output[j] = that value
# - Otherwise 0

def predict_simple_merge(row):
    left = row[:4]
    right = row[5:]
    out = []
    for j in range(4):
        if right[j] == 2:
            out.append(2)
        elif left[j] == 1:
            out.append(1)
        else:
            out.append(0)
    return out

print("Testing simple merge (right priority):")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    print(f"\n{demo_name}:")
    for i in range(4):
        row_out = list(predict_simple_merge(input_rows[i]))
        match = row_out == list(output_rows[i])
        print(f"  Row {i}: pred={row_out}, expected={list(output_rows[i])}, match={match}")

# Rule with stricter cascade: if ANY 2 at right[3] (farthest from separator), keep ALL 2s
#   otherwise, left-only priority

def predict_strict_cascade(row):
    """If 2s at farthest position (right col 3), use full merge. Else, left-only."""
    left = row[:4]
    right = row[5:]

    # Check if 2 at farthest position (right[3])
    has_farthest_2 = right[3] == 2

    if has_farthest_2:
        # Full merge with right priority
        out = []
        for j in range(4):
            if right[j] == 2:
                out.append(2)
            elif left[j] == 1:
                out.append(1)
            else:
                out.append(0)
        return out
    else:
        # Left-only
        out = []
        for j in range(4):
            if left[j] == 1:
                out.append(1)
            elif right[j] == 2 and left[j] == 1:  # 2 only if left has 1 at same position
                out.append(2)
            else:
                out.append(0)
        return out

print("Testing strict cascade (only right[3] triggers merge):")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    print(f"\n{demo_name}:")
    for i in range(4):
        row_out = list(predict_strict_cascade(input_rows[i]))
        match = row_out == list(output_rows[i])
        right = input_rows[i][5:]
        print(f"  Row {i}: right={right}[last={right[3]}], pred={row_out}, expected={list(output_rows[i])}, match={match}")

# Rule: 2s only kept at safe positions [1,2,3] (not at right[0])
#   Also need to handle the "cascade" effect from D1

def predict_safe_positions(row):
    """First pass: 2s only at safe positions [1,2,3]. Second pass: cascade to all 2s if any safe 2s exist?"""
    left = row[:4]
    right = row[5:]

    # Pass 1: simple merge at safe positions only
    out = []
    for j in range(4):
        if j in [1, 2, 3] and right[j] == 2:  # 2 at safe position
            out.append(2)
        elif left[j] == 1:
            out.append(1)
        else:
            out.append(0)

    # Check if any 2s were added (cascade check)
    has_added_2 = any(out[j] == 2 for j in [1, 2, 3])

    if has_added_2:
        # Pass 2: cascade - keep ALL 2s now that safe ones triggered merge
        out = []
        for j in range(4):
            if right[j] == 2:
                out.append(2)
            elif left[j] == 1:
                out.append(1)
            else:
                out.append(0)

    return out

print("Testing safe positions with cascade:")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    print(f"\n{demo_name}:")
    for i in range(4):
        row_out = list(predict_safe_positions(input_rows[i]))
        match = row_out == list(output_rows[i])
        right = input_rows[i][5:]
        print(f"  Row {i}: right={right}[0={right[0]}], pred={row_out}, expected={list(output_rows[i])}, match={match}")

# Rule: if ANY 2 at right positions 2 or 3 (cols 7 or 8), do full merge
#   otherwise, do left-only with conditional 2s (2 only kept if left has 1 at same pos)

def predict_final_fixed(row):
    """
    Full merge if any 2 at right[2:4] (safe zones)
    Left-only otherwise
    """
    left = row[:4]
    right = row[5:]

    # Check safe zone (right[2:4] = input cols 7-8)
    has_safe_2 = right[2] == 2 or right[3] == 2

    if has_safe_2:
        # Full merge: right takes priority over left
        out = []
        for j in range(4):
            if right[j] == 2:
                out.append(2)
            elif left[j] == 1:
                out.append(1)
            else:
                out.append(0)
        return out
    else:
        # Left-only: 2s only if left has 1 at same position
        out = []
        for j in range(4):
            if left[j] == 1:
                out.append(1)
            elif right[j] == 2 and left[j] == 1:
                out.append(2)
            else:
                out.append(0)
        return out

print("Testing fixed rule:")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    print(f"\n{demo_name}:")
    for i in range(4):
        row_out = list(predict_final_fixed(input_rows[i]))
        match = row_out == list(output_rows[i])
        has_safe = input_rows[i][7] == 2 or input_rows[i][8] == 2
        print(f"  Row {i}: right={list(input_rows[i][5:])}[pos2={input_rows[i][7]},pos3={input_rows[i][8]}]={has_safe}, pred={row_out}, expected={list(output_rows[i])}, match={match}")

# Hypothesis: check right[0] (col 5, closest to separator)
# If right[0] == 2, use D1 merge rule
# If right[0] == 0, use D2 left-only rule

def predict_by_right_col0(row):
    left = row[:4]
    right = row[5:]

    if right[0] == 2:
        # D1 merge: right 2s replace left 0s
        out = []
        for j in range(4):
            if right[j] == 2:
                out.append(2)
            elif left[j] == 1:
                out.append(1)
            else:
                out.append(0)
        return out
    else:
        # D2 left-only: just keep left, ignore right
        return list(left)

print("Testing right[0] rule:")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    print(f"\n{demo_name}:")
    for i in range(4):
        row_out = list(predict_by_right_col0(input_rows[i]))
        match = row_out == list(output_rows[i])
        print(f"  Row {i}: right[0]={input_rows[i][5]}, pred={row_out}, expected={list(output_rows[i])}, match={match}")

# Test on test input
test_rows = [[1,1,1,1,5,2,0,0,0], [0,1,1,0,5,2,2,2,2], [0,1,1,0,5,2,0,0,0], [0,0,0,0,5,0,0,0,0]]
print("\n\nTest input with right[0] rule:")
for i, row in enumerate(test_rows):
    pred = list(predict_by_right_col0(row))
    print(f"  Row {i}: right[0]={row[5]}, pred={pred}")

prediction = [[list(predict_by_right_col0(row)) for row in test_rows]]
print(f"\nFull prediction: {prediction}")

# Check if there's ANY overlap anywhere in D1 vs D2
print("Checking for ANY overlaps in demo:")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    any_overlaps_in_demo = False
    for i in range(4):
        left = input_rows[i][:4]
        right = input_rows[i][5:]
        overlaps = [j for j in range(4) if left[j] == 1 and right[j] == 2]
        if overlaps:
            print(f"{demo_name} Row {i}: has overlaps at {overlaps}")
            any_overlaps_in_demo = True
    if not any_overlaps_in_demo:
        print(f"{demo_name}: NO overlaps in any row")

# Simpler rule: 2s replace left 0s; 1s stay or become 2 if overlapping

def predict_simpler(row):
    left = row[:4]
    right = row[5:]

    out = []
    for j in range(4):
        if right[j] == 2 and left[j] == 0:
            # Left is 0, right has 2 → replace with 2
            out.append(2)
        elif right[j] == 2 and left[j] == 1:
            # Overlap: 1 vs 2. Left wins (D2 behavior)
            out.append(1)
        elif left[j] == 1:
            out.append(1)
        else:
            out.append(0)

    return out

print("Testing simpler rule (1s always win over 2s):")
for demo_name, (input_rows, output_rows) in [("D1", (demo1_input, demo1_output)), ("D2", (demo2_input, demo2_output))]:
    print(f"\n{demo_name}:")
    for i in range(4):
        row_out = list(predict_simpler(input_rows[i]))
        match = row_out == list(output_rows[i])
        print(f"  Row {i}: pred={row_out}, expected={list(output_rows[i])}, match={match}")

